export type Lang = 'de' | 'en';
export type LangPref = 'auto' | Lang;
const LANG_KEY = 'mahlwerk.lang';

export function langPref(): LangPref {
  try {
    const stored = localStorage.getItem(LANG_KEY);
    if (stored === 'de' || stored === 'en') return stored;
  } catch { /* storage blocked: automatic */ }
  return 'auto';
}
const detect = (): Lang => ((navigator.language || 'en').toLowerCase().startsWith('de') ? 'de' : 'en');
/** The language of this page load. Texts and number formats are computed once, so a change takes effect by reloading. */
export const lang: Lang = langPref() === 'auto' ? detect() : (langPref() as Lang);
document.documentElement.lang = lang;

/** Remember the choice on this device and reload the page so that every text, number and date follows it at once. */
export function setLangPref(pref: LangPref) {
  try {
    if (pref === 'auto') localStorage.removeItem(LANG_KEY); else localStorage.setItem(LANG_KEY, pref);
  } catch { /* nothing to remember it in; the reload still shows the browser language */ }
  location.reload();
}

const dict: Record<Lang, Record<string, string>> = { en, de };

export function t(key: Key | `w_${string}` | `hint_${string}` | `hintT_${string}` | `n_${string}` | `rev_${string}` | `badge_${string}` | `badgeCond_${string}` | `badgeProg_${string}` | `adm_${string}` | `cn_${string}` | `cnD_${string}` | `ev_${string}` | `wk_${string}` | `cbCnt_${string}` | `cbErr_${string}` | `cbReason_${string}`, vars: Record<string, string | number> = {}): string {
  const text = dict[lang][key] ?? dict.en[key] ?? key;
  return text.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));
}

export const fmt = (v: number, digits = 0) =>
  v.toLocaleString(lang, { maximumFractionDigits: digits });
export const fmtDate = (unixSeconds: number) =>
  new Date(unixSeconds * 1000).toLocaleDateString(lang, { day: '2-digit', month: '2-digit', year: 'numeric' });
export const fmt1 = (v: number) => fmt(v, 1);
/** Number for an input field: locale decimal separator, no grouping. */
export const inputNumber = (v: number | null | undefined) =>
  v == null ? '' : v.toLocaleString(lang, { maximumFractionDigits: 2, useGrouping: false });
/** Parse a typed number ("1,5" or "1.5"); null for empty, NaN for garbage. */
export function parseNumber(raw: string): number | null {
  const s = raw.trim().replace(',', '.');
  if (s === '') return null;
  return /^\d*\.?\d+$|^\d+\.$/.test(s) ? Number(s) : NaN;
}
